import { useEffect, useRef } from "react";
import { Terminal as XTerm } from "xterm";
import { FitAddon } from "xterm-addon-fit";
import "xterm/css/xterm.css";
// @ts-ignore wailsjs bindings are generated by wails build
import { ResizeSSHShell, WriteSSHShell } from "../../../wailsjs/go/controllers/SSH";
// @ts-ignore wailsjs bindings are generated by wails build
import { EventsOn } from "../../../wailsjs/runtime";

// One xterm.js instance per remote SSH shell. Output arrives as ssh:data
// events tagged with the shell ID; keystrokes flow back through
// WriteSSHShell and pane resizes through ResizeSSHShell.
export default function RemoteTerminal({
  shellId,
  onExit,
}: {
  shellId: string;
  onExit?: () => void;
}) {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!containerRef.current) return;
    const term = new XTerm({
      cursorBlink: true,
      cursorStyle: "block",
      fontSize: 13,
      fontFamily: "JetBrains Mono, Menlo, monospace",
      scrollback: 5000,
      theme: {
        background: "#171717",
        foreground: "#e4e6ff",
        cursor: "#7c5cff",
        selectionBackground: "#3d3d6b",
      },
    });
    const fit = new FitAddon();
    term.loadAddon(fit);
    term.open(containerRef.current);
    const doFit = () => {
      try {
        fit.fit();
      } catch {
        /* not yet laid out */
      }
    };
    doFit();

    const cancelData = EventsOn("ssh:data", (payload: { id: string; data: string }) => {
      if (payload?.id === shellId) term.write(payload.data);
    });
    const cancelExit = EventsOn("ssh:exit", (payload: { id: string }) => {
      if (payload?.id === shellId) {
        term.write("\r\n\x1b[90m[disconnected]\x1b[0m\r\n");
        onExit?.();
      }
    });
    term.onData((data) => {
      WriteSSHShell(shellId, data).catch(() => {
        /* shell died */
      });
    });
    const observer = new ResizeObserver(() => {
      doFit();
      if (term.cols > 0 && term.rows > 0) {
        ResizeSSHShell(shellId, term.cols, term.rows).catch(() => {
          /* dead */
        });
      }
    });
    observer.observe(containerRef.current);

    return () => {
      cancelData?.();
      cancelExit?.();
      observer.disconnect();
      term.dispose();
    };
  }, [shellId]); // eslint-disable-line react-hooks/exhaustive-deps

  return <div ref={containerRef} className="h-full w-full overflow-hidden" />;
}
